pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

contract InvMutTest is Test {
    MultiplicatorX4 c;
    function setUp() public { c = new MultiplicatorX4(); }

    function testFuzz_property(uint256 amount, bool useFailingCallee) public {
        amount = bound(amount, 0, 1 ether);

        Reverter rev = new Reverter();
        Accepting acc = new Accepting();

        address callee = useFailingCallee ? address(rev) : address(acc);

        vm.deal(address(this), amount);

        bool ok;
        try c.Command{value: amount}(callee, "0x") {
            ok = true;
        } catch {
            ok = false;
        }

        assertTrue(ok);
    }
}

contract Reverter {
    fallback() external payable {
        revert("revert");
    }
    receive() external payable {
        revert("revert");
    }
}

contract Accepting {
    fallback() external payable {}
    receive() external payable {}
}
